import{_ as e,o as r,c as t,a2 as a}from"./chunks/framework.BZO4qERu.js";const g=JSON.parse('{"title":"Настройка канала Discord","description":"","frontmatter":{},"headers":[],"relativePath":"ru/integrations/channels/discord.md","filePath":"ru/integrations/channels/discord.md","lastUpdated":1792323081000}'),l={name:"ru/integrations/channels/discord.md"};function s(i,o,d,n,c,h){return r(),t("div",null,[...o[0]||(o[0]=[a('<h1 id="настроика-канала-discord" tabindex="-1">Настройка канала Discord <a class="header-anchor" href="#настроика-канала-discord" aria-label="Permalink to &quot;Настройка канала Discord&quot;">​</a></h1><p>Подключите своего Bot в Memoh к Discord, чтобы он присоединялся к серверам и общался с участниками сообщества в каналах и личных сообщениях.</p><h2 id="предварительные-условия" tabindex="-1">Предварительные условия <a class="header-anchor" href="#предварительные-условия" aria-label="Permalink to &quot;Предварительные условия&quot;">​</a></h2><ul><li>Аккаунт Discord с доступом к <a href="https://discord.com/developers/applications" target="_blank" rel="noreferrer">Discord Developer Portal</a>.</li><li>Сервер Discord, на который вы можете авторизовать Bot.</li><li>Bot в Memoh; каналы настраиваются на его вкладке <strong>Platforms</strong>.</li></ul><h2 id="шаги" tabindex="-1">Шаги <a class="header-anchor" href="#шаги" aria-label="Permalink to &quot;Шаги&quot;">​</a></h2><h3 id="_1-в-discord-developer-portal-создаите-приложение-и-получите-токен-bot" tabindex="-1">1. В Discord Developer Portal создайте приложение и получите токен Bot <a class="header-anchor" href="#_1-в-discord-developer-portal-создаите-приложение-и-получите-токен-bot" aria-label="Permalink to &quot;1. В Discord Developer Portal создайте приложение и получите токен Bot&quot;">​</a></h3><ol><li>Откройте <a href="https://discord.com/developers/applications" target="_blank" rel="noreferrer">Discord Developer Portal</a>.</li><li>Нажмите <strong>New Application</strong> и укажите название.</li><li>В левой панели перейдите в раздел <strong>Bot</strong>.</li><li>Нажмите <strong>Reset Token</strong>, чтобы сгенерировать <strong>Bot Token</strong>. Скопируйте его и храните в надёжном месте.</li></ol><h3 id="_2-в-discord-developer-portal-включите-привилегированные-интенты" tabindex="-1">2. В Discord Developer Portal включите привилегированные интенты <a class="header-anchor" href="#_2-в-discord-developer-portal-включите-привилегированные-интенты" aria-label="Permalink to &quot;2. В Discord Developer Portal включите привилегированные интенты&quot;">​</a></h3><ol><li>На странице <strong>Bot</strong> прокрутите вниз до раздела <strong>Privileged Gateway Intents</strong>.</li><li>Включите <code>Message Content Intent</code>, <code>Server Members Intent</code> и <code>Presence Intent</code>.</li><li>Сохраните изменения.</li></ol><h3 id="_3-в-discord-developer-portal-пригласите-bot-на-сервер" tabindex="-1">3. В Discord Developer Portal пригласите Bot на сервер <a class="header-anchor" href="#_3-в-discord-developer-portal-пригласите-bot-на-сервер" aria-label="Permalink to &quot;3. В Discord Developer Portal пригласите Bot на сервер&quot;">​</a></h3><ol><li>Перейдите в <strong>OAuth2</strong> &gt; <strong>URL Generator</strong>.</li><li>Отметьте scope: <code>bot</code>, <code>applications.commands</code>.</li><li>Отметьте права: <code>Send Messages</code>, <code>Read Message History</code>, <code>Embed Links</code>, <code>Attach Files</code>.</li><li>Скопируйте сгенерированный URL и откройте его в браузере.</li><li>Выберите сервер, на который хотите добавить Bot, и авторизуйте его.</li></ol><blockquote><p>Официальное руководство: <a href="https://discord.com/developers/docs/intro" target="_blank" rel="noreferrer">Discord Developer Portal - Bots</a></p></blockquote><h3 id="_4-в-memoh-добавьте-канал-discord" tabindex="-1">4. В Memoh добавьте канал Discord <a class="header-anchor" href="#_4-в-memoh-добавьте-канал-discord" aria-label="Permalink to &quot;4. В Memoh добавьте канал Discord&quot;">​</a></h3><ol><li>Откройте страницу нужного Bot и перейдите на вкладку <strong>Platforms</strong>.</li><li>Нажмите <strong>Add Channel</strong> и выберите <strong>Discord</strong>.</li><li>Вставьте <strong>Bot Token</strong>.</li><li>Нажмите <strong>Save and Enable</strong>.</li></ol><h2 id="учетные-данные" tabindex="-1">Учётные данные <a class="header-anchor" href="#учетные-данные" aria-label="Permalink to &quot;Учётные данные&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Поле</th><th>Описание</th></tr></thead><tbody><tr><td><strong>Bot Token</strong></td><td>Генерируется кнопкой <strong>Reset Token</strong> на странице <strong>Bot</strong> приложения. Храните его в надёжном месте.</td></tr></tbody></table><h2 id="проверка" tabindex="-1">Проверка <a class="header-anchor" href="#проверка" aria-label="Permalink to &quot;Проверка&quot;">​</a></h2><p>Отправьте Bot личное сообщение <code>/help</code> или обратитесь к нему через @-упоминание в канале сервера, на который он добавлен. Если Bot ответил списком команд, канал работает.</p><h2 id="групповые-чаты" tabindex="-1">Групповые чаты <a class="header-anchor" href="#групповые-чаты" aria-label="Permalink to &quot;Групповые чаты&quot;">​</a></h2><p>Серверы Discord поддерживаются. После авторизации Bot на сервере обращайтесь к нему в канале через @-упоминание.</p><h2 id="отключение-и-смена-учетных-данных" tabindex="-1">Отключение и смена учётных данных <a class="header-anchor" href="#отключение-и-смена-учетных-данных" aria-label="Permalink to &quot;Отключение и смена учётных данных&quot;">​</a></h2><p>Отключить или удалить этот канал можно в любой момент на вкладке <strong>Platforms</strong> нужного Bot. Чтобы сменить токен, обновите поле <strong>Bot Token</strong> и сохраните.</p>',22)])])}const b=e(l,[["render",s]]);export{g as __pageData,b as default};
